<script setup lang="ts">
import { computed, ref } from 'vue';
import UiParentCard from '@/components/shared/UiParentCard.vue';
import UiModal from '@/components/shared/UiModal.vue';
import type { AdmissionAction, AdmissionSection, AdmissionStage } from '../convocatorias.mock';

const props = defineProps<{ convocatoriaId: string; stages: AdmissionStage[] }>();
const emit = defineEmits<{ 'update:stages': [stages: AdmissionStage[]] }>();
type Tab = 'content' | 'connections' | 'settings';
const editing = ref<AdmissionStage | null>(null); const tab = ref<Tab>('content'); const message = ref(''); const deleting = ref<AdmissionStage | null>(null);
const sectionDialog = ref<AdmissionSection | null>(null); const actionDialog = ref<{ sectionId: string; action: AdmissionAction } | null>(null);
// UiModal implements the v-model:show contract. Keeping these adapters avoids
// passing a one-way Boolean expression to a modal that can also close itself.
const showSectionDialog = computed({ get: () => Boolean(sectionDialog.value), set: (show: boolean) => { if (!show) sectionDialog.value = null; } });
const showActionDialog = computed({ get: () => Boolean(actionDialog.value), set: (show: boolean) => { if (!show) actionDialog.value = null; } });
const ordered = computed(() => [...props.stages].sort((a, b) => a.orden - b.orden));
const sections = computed(() => editing.value?.secciones || []);
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const actionCount = (stage: AdmissionStage) => (stage.secciones || []).reduce((sum, section) => sum + section.acciones.length, 0);
const normalize = (items: AdmissionStage[]) => items.map((stage, index) => ({ ...stage, orden: index + 1, workflowIds: stage.workflowIds || [], secciones: stage.secciones || [], connectionIds: stage.connectionIds || [] }));
function newStage(): AdmissionStage { return { id: `stage-${Date.now()}`, convocatoriaId: props.convocatoriaId, nombre: '', descripcion: '', orden: ordered.value.length + 1, fechaInicio: '', fechaCierre: '', fechaPublicacion: '', workflowIds: [], secciones: [], connectionIds: [] }; }
function begin(stage?: AdmissionStage) { editing.value = normalize([clone(stage || newStage())])[0]; tab.value = 'content'; }
function save(close = true) { if (!editing.value) return; if (!editing.value.nombre.trim()) { tab.value = 'settings'; message.value = 'Ingrese un nombre para la etapa.'; return; } const list = [...props.stages]; const index = list.findIndex((stage) => stage.id === editing.value?.id); const value = clone({ ...editing.value, nombre: editing.value.nombre.trim() }); if (index < 0) list.push(value); else list.splice(index, 1, value); emit('update:stages', normalize(list)); if (close) { editing.value = null; message.value = 'Etapa guardada localmente.'; } }
function moveStage(index: number, delta: number) { const list = ordered.value; const target = index + delta; if (target < 0 || target >= list.length) return; [list[index], list[target]] = [list[target], list[index]]; emit('update:stages', normalize(list)); }
function duplicate(stage: AdmissionStage) { const copy = clone(stage); copy.id = `stage-${Date.now()}`; copy.nombre += ' (copia)'; copy.orden = ordered.value.length + 1; copy.connectionIds = []; emit('update:stages', normalize([...props.stages, copy])); message.value = 'Etapa duplicada.'; }
function removeStage() { if (!deleting.value) return; const id = deleting.value.id; emit('update:stages', normalize(props.stages.filter((stage) => stage.id !== id).map((stage) => ({ ...stage, connectionIds: (stage.connectionIds || []).filter((value) => value !== id) })))); deleting.value = null; message.value = 'Etapa y conexiones relacionadas eliminadas.'; }
function newSection() { sectionDialog.value = { id: `section-${Date.now()}`, nombre: '', descripcion: '', orden: sections.value.length + 1, acciones: [] }; }
function saveSection() { if (!editing.value || !sectionDialog.value?.nombre.trim()) return; const list = clone(editing.value.secciones || []); const index = list.findIndex((section) => section.id === sectionDialog.value?.id); if (index < 0) list.push(sectionDialog.value); else list.splice(index, 1, sectionDialog.value); editing.value.secciones = list.map((section, index) => ({ ...section, nombre: section.nombre.trim(), orden: index + 1 })); sectionDialog.value = null; }
function moveSection(index: number, delta: number) { if (!editing.value) return; const list = clone(sections.value); const target = index + delta; if (target < 0 || target >= list.length) return; [list[index], list[target]] = [list[target], list[index]]; editing.value.secciones = list.map((section, order) => ({ ...section, orden: order + 1 })); }
function newAction(sectionId: string) { actionDialog.value = { sectionId, action: { id: `action-${Date.now()}`, nombre: '', tipo: 'Validación', descripcion: '', orden: 1 } }; }
function moveAction(sectionId: string, index: number, delta: number) { const section = (editing.value?.secciones || []).find((item) => item.id === sectionId); if (!section) return; const target = index + delta; if (target < 0 || target >= section.acciones.length) return; [section.acciones[index], section.acciones[target]] = [section.acciones[target], section.acciones[index]]; section.acciones = section.acciones.map((action, order) => ({ ...action, orden: order + 1 })); }
function saveAction() { if (!editing.value || !actionDialog.value?.action.nombre.trim()) return; const section = (editing.value.secciones || []).find((item) => item.id === actionDialog.value?.sectionId); if (!section || !actionDialog.value) return; const action = actionDialog.value.action; const index = section.acciones.findIndex((item) => item.id === action.id); if (index < 0) section.acciones.push({ ...action, nombre: action.nombre.trim(), orden: section.acciones.length + 1 }); else section.acciones.splice(index, 1, { ...action, nombre: action.nombre.trim() }); actionDialog.value = null; }
function addConnection(id: string | null) { if (!editing.value || !id || id === editing.value.id || (editing.value.connectionIds || []).includes(id)) return; editing.value.connectionIds = [...(editing.value.connectionIds || []), id]; }
function openConnection(id: string) { save(false); const stage = props.stages.find((item) => item.id === id); if (stage) begin(stage); }
</script>

<template>
  <v-alert v-if="message" type="success" variant="tonal" density="compact" closable class="mb-4" @click:close="message = ''">{{ message }}</v-alert>
  <template v-if="editing">
    <v-btn variant="text" class="px-0 mb-4" prepend-icon="mdi-arrow-left" @click="save()">Volver a etapas</v-btn>
    <UiParentCard :title="editing.nombre || 'Nueva etapa'" icon="mdi-format-list-bulleted-square"><template #action><v-btn size="small" color="primary" @click="save">Guardar etapa</v-btn></template>
      <v-tabs v-model="tab"><v-tab value="content">Contenido</v-tab><v-tab value="connections">Conexiones</v-tab><v-tab value="settings">Ajustes</v-tab></v-tabs><v-divider class="mb-5" />
      <div v-if="tab === 'content'"><div class="d-flex flex-wrap justify-space-between align-center ga-3 mb-4"><div><div class="text-h6">Secciones y acciones</div><div class="text-body-2 text-medium-emphasis">Organiza el contenido de esta etapa.</div></div><v-btn color="primary" prepend-icon="mdi-plus" @click="newSection">Nueva sección</v-btn></div><v-empty-state v-if="!sections.length" icon="mdi-folder-outline" title="Aún no hay secciones" text="Crea una sección para comenzar." />
        <UiParentCard v-for="(section, index) in sections" :key="section.id" :title="section.nombre" :subtitle="section.descripcion || 'Sin descripción'" icon="mdi-folder-outline" class="mb-4"><template #action><v-btn size="small" variant="text" icon="mdi-pencil" @click="sectionDialog = clone(section)" /><v-btn size="small" variant="text" icon="mdi-arrow-up" :disabled="index === 0" @click="moveSection(index, -1)" /><v-btn size="small" variant="text" icon="mdi-arrow-down" :disabled="index === sections.length - 1" @click="moveSection(index, 1)" /><v-btn size="small" variant="text" color="error" icon="mdi-delete-outline" @click="editing.secciones = sections.filter(item => item.id !== section.id)" /></template><div v-if="!section.acciones.length" class="text-body-2 text-medium-emphasis mb-3">No hay acciones en esta sección.</div><v-card v-for="(action, actionIndex) in section.acciones" :key="action.id" variant="outlined" class="mb-2"><v-card-text class="d-flex align-center justify-space-between py-3"><div><div class="font-weight-medium">{{ action.nombre }}</div><div class="text-caption text-medium-emphasis">{{ action.tipo }}<span v-if="action.descripcion"> · {{ action.descripcion }}</span></div></div><div><v-btn size="small" variant="text" icon="mdi-arrow-up" :disabled="actionIndex === 0" @click="moveAction(section.id, actionIndex, -1)" /><v-btn size="small" variant="text" icon="mdi-arrow-down" :disabled="actionIndex === section.acciones.length - 1" @click="moveAction(section.id, actionIndex, 1)" /><v-btn size="small" variant="text" icon="mdi-pencil" @click="actionDialog = { sectionId: section.id, action: clone(action) }" /><v-btn size="small" variant="text" color="error" icon="mdi-delete-outline" @click="section.acciones = section.acciones.filter(item => item.id !== action.id)" /></div></v-card-text></v-card><v-btn size="small" variant="tonal" color="primary" prepend-icon="mdi-plus" @click="newAction(section.id)">Agregar acción</v-btn></UiParentCard></div>
      <div v-else-if="tab === 'connections'"><div class="text-h6">Conexiones de la etapa</div><p class="text-body-2 text-medium-emphasis mb-5">Define las etapas a las que podrá continuar el proceso.</p><v-select :items="ordered.filter(stage => stage.id !== editing?.id && !(editing?.connectionIds || []).includes(stage.id))" item-title="nombre" item-value="id" label="Agregar conexión hacia" clearable @update:model-value="addConnection" /><v-empty-state v-if="!(editing.connectionIds || []).length" icon="mdi-source-branch" title="Sin conexiones configuradas" text="Seleccione una etapa destino para crear una conexión." /><v-list v-else border rounded><v-list-item v-for="id in editing.connectionIds || []" :key="id" :title="ordered.find(stage => stage.id === id)?.nombre || 'Etapa no disponible'" prepend-icon="mdi-arrow-right-circle-outline"><template #append><v-btn size="small" variant="text" icon="mdi-open-in-new" @click="openConnection(id)" /><v-btn size="small" variant="text" color="error" icon="mdi-delete-outline" @click="editing.connectionIds = editing.connectionIds?.filter(value => value !== id)" /></template></v-list-item></v-list></div>
      <v-row v-else><v-col cols="12" md="7"><v-text-field v-model="editing.nombre" label="Nombre de etapa" /></v-col><v-col cols="12" md="5"><v-textarea v-model="editing.descripcion" label="Descripción" rows="1" auto-grow /></v-col><v-col cols="12" md="4"><v-text-field v-model="editing.fechaInicio" type="datetime-local" label="Fecha y hora de inicio" /></v-col><v-col cols="12" md="4"><v-text-field v-model="editing.fechaCierre" type="datetime-local" label="Cierre de actividades" /></v-col><v-col cols="12" md="4"><v-text-field v-model="editing.fechaPublicacion" type="datetime-local" label="Publicación de resultados" /></v-col></v-row>
    </UiParentCard>
  </template>
  <template v-else><div class="d-flex flex-wrap align-end justify-space-between mb-5 ga-3"><div><div class="text-h6 font-weight-semibold">Etapas de admisión</div><div class="text-body-2 text-medium-emphasis">Administra etapas, contenido y conexiones del proceso.</div></div><v-btn color="primary" prepend-icon="mdi-plus" @click="begin()">Nueva etapa</v-btn></div><UiParentCard v-if="!ordered.length" title="Etapas de admisión" icon="mdi-format-list-bulleted-square"><v-empty-state icon="mdi-calendar-outline" title="Aún no hay etapas" text="Cree la primera etapa para construir el proceso de admisión."><template #actions><v-btn color="primary" @click="begin()">Crear primera etapa</v-btn></template></v-empty-state></UiParentCard><v-row v-else><v-col v-for="(stage, index) in ordered" :key="stage.id" cols="12" md="6" lg="4"><UiParentCard :title="stage.nombre" :subtitle="stage.descripcion || 'Sin descripción'" icon="mdi-format-list-bulleted-square" class="h-100"><template #action><v-menu><template #activator="{ props: menuProps }"><v-btn v-bind="menuProps" icon="mdi-dots-vertical" variant="text" size="small" /></template><v-list density="compact"><v-list-item title="Editar" @click="begin(stage)" /><v-list-item title="Duplicar" @click="duplicate(stage)" /><v-list-item title="Eliminar" base-color="error" @click="deleting = stage" /></v-list></v-menu></template><div class="d-flex flex-wrap ga-2 mb-4"><v-chip size="small" variant="tonal">{{ (stage.secciones || []).length }} secciones</v-chip><v-chip size="small" variant="tonal">{{ actionCount(stage) }} acciones</v-chip><v-chip size="small" variant="tonal">{{ (stage.connectionIds || []).length }} conexiones</v-chip></div><div class="d-flex justify-space-between"><v-btn size="small" variant="tonal" color="primary" @click="begin(stage)">Configurar</v-btn><div><v-btn size="small" variant="text" icon="mdi-arrow-up" :disabled="index === 0" @click="moveStage(index, -1)" /><v-btn size="small" variant="text" icon="mdi-arrow-down" :disabled="index === ordered.length - 1" @click="moveStage(index, 1)" /></div></div></UiParentCard></v-col></v-row></template>
  <UiModal :show="Boolean(deleting)" title="Eliminar etapa" persistent @update:show="deleting = null"><p>Se eliminará <b>{{ deleting?.nombre }}</b> y se retirarán sus conexiones entrantes y salientes.</p><template #footer-actions><v-btn variant="text" @click="deleting = null">Cancelar</v-btn><v-btn color="error" @click="removeStage">Eliminar</v-btn></template></UiModal>
  <UiModal v-model:show="showSectionDialog" title="Configurar sección" persistent><template v-if="sectionDialog"><v-text-field v-model="sectionDialog.nombre" label="Nombre de sección" /><v-textarea v-model="sectionDialog.descripcion" label="Descripción" rows="2" auto-grow /></template><template #footer-actions><v-btn variant="text" @click="sectionDialog = null">Cancelar</v-btn><v-btn color="primary" :disabled="!sectionDialog?.nombre.trim()" @click="saveSection">Guardar sección</v-btn></template></UiModal>
  <UiModal v-model:show="showActionDialog" title="Configurar acción" persistent><template v-if="actionDialog"><v-text-field v-model="actionDialog.action.nombre" label="Nombre de acción" /><v-select v-model="actionDialog.action.tipo" :items="['Validación', 'Formulario', 'Entrevista', 'Notificación']" label="Tipo de acción" /><v-textarea v-model="actionDialog.action.descripcion" label="Descripción" rows="2" auto-grow /></template><template #footer-actions><v-btn variant="text" @click="actionDialog = null">Cancelar</v-btn><v-btn color="primary" :disabled="!actionDialog?.action.nombre.trim()" @click="saveAction">Guardar acción</v-btn></template></UiModal>
</template>
